import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Housing and renting","description":"How an authenticated lease connects to your Kahramaa account, how to move in, pay bills, use prepaid service and report a fault.","frontmatter":{"title":"Housing and renting","description":"How an authenticated lease connects to your Kahramaa account, how to move in, pay bills, use prepaid service and report a fault.","lastChecked":"2026-10","sourceCount":7},"headers":[],"relativePath":"guide/housing-and-utilities.md","filePath":"guide/housing-and-utilities.md"}'),s={name:"guide/housing-and-utilities.md"};function i(n,e,f,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="housing-and-renting" tabindex="-1">Housing and renting <a class="header-anchor" href="#housing-and-renting" aria-label="Permalink to &quot;Housing and renting&quot;">​</a></h1><p>If you rent a home in Qatar, two things tie together: your lease, which is authenticated through the Ministry of Municipality, and your electricity and water account with Kahramaa. Kahramaa&#39;s move-in form asks for that authenticated lease.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><h2 id="your-lease" tabindex="-1">Your lease <a class="header-anchor" href="#your-lease" aria-label="Permalink to &quot;Your lease&quot;">​</a></h2><ul><li>Lease services are on the Ministry of Municipality website. You log in through the National Authentication System, open the e-services and choose the property lease contract services.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></li><li>The Ministry&#39;s guide says renewals can be done online, without visiting a municipality office or carrying paper documents.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></li><li>A landlord can give someone electronic authorisation to handle requests to register, change, renew or end a lease.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li>After the municipality approves a renewal, you can print the new certificate from &quot;My requests&quot;. A link to it is also sent by SMS and email.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup></li></ul><h2 id="moving-in-your-kahramaa-account" tabindex="-1">Moving in: your Kahramaa account <a class="header-anchor" href="#moving-in-your-kahramaa-account" aria-label="Permalink to &quot;Moving in: your Kahramaa account&quot;">​</a></h2><p>Kahramaa handles this through its Move to New Premises service. Have these ready:<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><ul><li>Your electricity number, and your water number if you have it.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>Your RNR number, which is the authentication number for your rental agreement issued by the Ministry of Municipality.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>Your QID number and expiry date, or your establishment ID, plus a copy.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>A copy of your rental agreement authenticated by the municipality. Owners do not need this one.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li><li>Your lease start and end dates, payment frequency and rent amount.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></li><li>Your move-in date, email, mobile number, P.O. box and address.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li></ul><p>The form lets either you or Kahramaa take the meter reading.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></p><h2 id="paying-your-bills" tabindex="-1">Paying your bills <a class="header-anchor" href="#paying-your-bills" aria-label="Permalink to &quot;Paying your bills&quot;">​</a></h2><ul><li>On Kahramaa&#39;s Bill Payment page, select your electricity number to see what is due. The page lists credit card, debit card and Apple Pay as payment methods.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></li><li>Prices are not quoted here. Use Kahramaa&#39;s tariff page and its calculator to see the current rates.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li></ul><h2 id="prepaid-service" tabindex="-1">Prepaid service <a class="header-anchor" href="#prepaid-service" aria-label="Permalink to &quot;Prepaid service&quot;">​</a></h2><p>Some customers can pay in advance instead of receiving bills. It is only for properties with smart meters, within size limits for the electricity breaker and water pipe.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></p><ul><li>You apply through the Kahramaa website or app, and the tariff is the same as a normal account.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></li><li>Kahramaa says no deposit is needed. There is a monthly meter rental of QAR 5.<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5]</a></sup></li><li>You get a warning when your balance drops to QAR 30, and service is cut if it reaches zero.<sup class="footnote-ref"><a href="#fn5" id="fnref5:3">[5]</a></sup></li><li>Switching back to a normal account is allowed only in certain exceptional cases.<sup class="footnote-ref"><a href="#fn5" id="fnref5:4">[5]</a></sup></li></ul><h2 id="reporting-a-fault" tabindex="-1">Reporting a fault <a class="header-anchor" href="#reporting-a-fault" aria-label="Permalink to &quot;Reporting a fault&quot;">​</a></h2><ul><li>Kahramaa&#39;s emergency line runs 24 hours a day: call 991 inside Qatar, or +974 4449 4000 from abroad.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li><li>You can also message Kahramaa on WhatsApp at +974 3030 3991, or use the support form on its website.<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6]</a></sup></li></ul><h2 id="rental-disputes" tabindex="-1">Rental disputes <a class="header-anchor" href="#rental-disputes" aria-label="Permalink to &quot;Rental disputes&quot;">​</a></h2><p>Qatar has a Rental Disputes Settlement Committee. The government services catalogue lists a Ministry of Justice service for attesting a power of attorney to act before it.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></p><p>See also: <a href="./residence-permit-and-qid">Residence permit and QID</a>, <a href="./metrash">Metrash</a>, <a href="./cost-of-living">Cost of living basics</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Kahramaa, <a href="https://www.km.qa/CustomerService/Pages/MoveToNewPremises.aspx" target="_blank" rel="noreferrer">Move to New Premises</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Ministry of Municipality, <a href="https://www.mm.gov.qa/cs/groups/public/documents/mmportal/njiw/mdq0/~edisp/mmpwcwsc011620044778.pdf" target="_blank" rel="noreferrer">Property lease contract services: renewal, user guide, May 2024</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Kahramaa, <a href="https://www.km.qa/CustomerService/Pages/BillPayment.aspx" target="_blank" rel="noreferrer">Bill Payment</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Kahramaa, <a href="https://www.km.qa/CustomerService/Pages/Tariff.aspx" target="_blank" rel="noreferrer">Tariff</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Kahramaa, <a href="https://www.km.qa/Pages/PrePaidService.aspx" target="_blank" rel="noreferrer">Prepaid Service</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Kahramaa, <a href="https://www.km.qa/Pages/contactus.aspx" target="_blank" rel="noreferrer">Contact Us</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Sharek government services catalogue, <a href="https://www.sharek.gov.qa/en/articles/ministry-of-justice/%D8%AA%D9%88%D8%AB%D9%8A%D9%82-%D8%AA%D9%88%D9%83%D9%8A%D9%84-%D8%B1%D8%B3%D9%85%D9%8A-%D8%AE%D8%A7%D8%B5-%D8%A3%D9%85%D8%A7%D9%85-%D9%84%D8%AC%D9%86%D8%A9-%D9%81%D8%B6-%D8%A7%D9%84%D9%85%D9%86%D8%A7%D8%B2%D8%B9%D8%A7%D8%AA-%D8%A7%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%D9%8A%D8%A9/676aba9f9619431ce6aa998c" target="_blank" rel="noreferrer">Attesting a special power of attorney before the Rental Disputes Settlement Committee</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',21)])])}const d=a(s,[["render",i]]);export{p as __pageData,d as default};
